import{_ as t,o as a,c as r,a3 as s}from"./chunks/framework.BLKCyc-R.js";const b=JSON.parse('{"title":"Interface: TessellationStep","description":"","frontmatter":{},"headers":[],"relativePath":"api/webgl/interfaces/TessellationStep.md","filePath":"api/webgl/interfaces/TessellationStep.md"}'),i={name:"api/webgl/interfaces/TessellationStep.md"};function o(d,e,n,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="interface-tessellationstep" tabindex="-1">Interface: TessellationStep <a class="header-anchor" href="#interface-tessellationstep" aria-label="Permalink to &quot;Interface: TessellationStep&quot;">​</a></h1><p>Defined in: <a href="https://github.com/sakuzu/maplibre-gl-draw/blob/517a091c571498d0a9ea4bcada119d73d348b1cd/src/view/terrain/tessellation.ts#L58" target="_blank" rel="noreferrer">src/view/terrain/tessellation.ts:58</a></p><p>How finely a line or a fill is subdivided to follow the terrain mesh, as <a href="/maplibre-gl-draw/api/webgl/functions/terrainTessellationStep.html">terrainTessellationStep</a> returns it.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Modifier</th><th>Type</th><th>Description</th><th>Defined in</th></tr></thead><tbody><tr><td><a id="property-coarsen"></a> <code>coarsen?</code></td><td><code>readonly</code></td><td><code>number</code></td><td>The coarsening factor applied to the tile step (a power of two; 1 = the actual mesh) Splitting at the actual mesh itself is ideal, but in a wide view the amount to split jumps. As long as we coarsen by a power of two, the split points keep sitting on a subset of the actual mesh nodes, so the problem of sinking along the valley bottoms does not occur (sinking happens when we leave the nodes). What remains is only that the chord dives slightly under a ridge, and that can be covered with a depth bias proportional to the step. Keep the factor small (TERRAIN_MAX_TILED_COARSEN).</td><td><a href="https://github.com/sakuzu/maplibre-gl-draw/blob/517a091c571498d0a9ea4bcada119d73d348b1cd/src/view/terrain/tessellation.ts#L109" target="_blank" rel="noreferrer">src/view/terrain/tessellation.ts:109</a></td></tr><tr><td><a id="property-grid"></a> <code>grid</code></td><td><code>readonly</code></td><td><code>number</code></td><td>Lattice interval (in Mercator units) The node interval of MapLibre&#39;s terrain mesh, 1/(2^z * meshSize), or that value coarsened by a power of two. Even when coarsened it still sits on a subset of the nodes.</td><td><a href="https://github.com/sakuzu/maplibre-gl-draw/blob/517a091c571498d0a9ea4bcada119d73d348b1cd/src/view/terrain/tessellation.ts#L65" target="_blank" rel="noreferrer">src/view/terrain/tessellation.ts:65</a></td></tr><tr><td><a id="property-maxpoints"></a> <code>maxPoints</code></td><td><code>readonly</code></td><td><code>number</code></td><td>Upper limit on the number of vertices that may be generated</td><td><a href="https://github.com/sakuzu/maplibre-gl-draw/blob/517a091c571498d0a9ea4bcada119d73d348b1cd/src/view/terrain/tessellation.ts#L67" target="_blank" rel="noreferrer">src/view/terrain/tessellation.ts:67</a></td></tr><tr><td><a id="property-region"></a> <code>region?</code></td><td><code>readonly</code></td><td><a href="/maplibre-gl-draw/api/webgl/interfaces/MercatorRect.html"><code>MercatorRect</code></a> | <code>null</code></td><td>The area that may be tessellated (in Mercator; null means no area = split anywhere) Elevation is read from the DEM atlas, but the atlas only covers the neighbourhood of the view, and outside it the value saturates at the edge value (<code>dem_elevation_meters</code> in <code>shaders/helpers.ts</code> clamps the uv). In other words, splitting finely outside the atlas only splits a flat surface finely while it stays flat, and the elevation does not change by a single metre. Splitting there anyway was the root of the slowness. With a dataset (8,172 administrative boundaries, all of Japan), the cost of splitting even the features that never appear on screen ate up the batch&#39;s tessellation budget, and the uniform coarsening applied to stay within the budget (up to 64x) reached even the features on screen. The chord of a coarse triangle dives below a hill, gets cut away by the depth test, and a hole opens in the fill. So we limit the area we split to the atlas (plus a margin). The cost is decided by how wide the view is and no longer depends on the number of records, so what is on screen can always be split at the finest step.</td><td><a href="https://github.com/sakuzu/maplibre-gl-draw/blob/517a091c571498d0a9ea4bcada119d73d348b1cd/src/view/terrain/tessellation.ts#L88" target="_blank" rel="noreferrer">src/view/terrain/tessellation.ts:88</a></td></tr><tr><td><a id="property-tiling"></a> <code>tiling?</code></td><td><code>readonly</code></td><td><a href="/maplibre-gl-draw/api/webgl/interfaces/TessellationTiling.html"><code>TessellationTiling</code></a> | <code>null</code></td><td>The actual mesh step of each terrain tile (if null, <code>grid</code> is used everywhere) MapLibre&#39;s terrain is drawn with a fixed lattice per tile, and in a pitched view the more distant the view is, the coarser the zoom of the tiles used. Matching the step to the tile&#39;s actual mesh makes our own surface agree with MapLibre&#39;s both on the nodes and inside the cells. If it is not matched, too fine a step sinks along the valley bottoms and too coarse a step dives under the ridges, and both are cut away by depth.</td><td><a href="https://github.com/sakuzu/maplibre-gl-draw/blob/517a091c571498d0a9ea4bcada119d73d348b1cd/src/view/terrain/tessellation.ts#L98" target="_blank" rel="noreferrer">src/view/terrain/tessellation.ts:98</a></td></tr></tbody></table>',5)])])}const u=t(i,[["render",o]]);export{b as __pageData,u as default};
